package com.smartsociety.platform.auth;
import com.smartsociety.platform.common.*; import com.smartsociety.platform.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final UserRepository repo; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(UserRepository r,PasswordEncoder e,JwtService j){repo=r;encoder=e;jwt=j;} @Transactional public AuthDtos.AuthResponse register(AuthDtos.RegisterRequest r){if(repo.findByEmailIgnoreCase(r.email()).isPresent())throw new DomainException(HttpStatus.CONFLICT,"Email already registered");var u=new User();u.setEmail(r.email().trim().toLowerCase());u.setFullName(r.fullName().trim());u.setPasswordHash(encoder.encode(r.password()));repo.save(u);return out(u);} public AuthDtos.AuthResponse login(AuthDtos.LoginRequest r){var u=repo.findByEmailIgnoreCase(r.email()).orElseThrow(()->new DomainException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));if(!encoder.matches(r.password(),u.getPasswordHash()))throw new DomainException(HttpStatus.UNAUTHORIZED,"Invalid credentials");return out(u);} private AuthDtos.AuthResponse out(User u){return new AuthDtos.AuthResponse(jwt.create(u.getId(),u.getEmail(),u.getRole().name()),"Bearer",u.getRole().name(),u.getFullName(),u.getEmail());} }
